  _ = `Review by Valve is required before this page can be set live`,
  _ = `This sale event is pending approval by Valve`,
  _ = `Please use the button to the right to submit your page for review at least 7 days ahead of your desired publish date to make sure there is time for review/approval and any necessary changes.`,
  _ = `The Steam Team will get in touch with you via the Steamworks Support ticket if there are any changes required to your page. You can view the the Steamworks support ticket, and add comments if necessary, by clicking the button to the right.`,
