  _ = `Marketing Message Major Update`,
  _ = `Make the title compelling and relevant for players. If this is truly one of the biggest updates of the year, the title should reflect that excitement. Avoid generic phrasing like <1>'Version 330.4 update.'</1> Instead, highlight what makes the update special.`,
  _ = `The key art must clearly showcase the update itself. Do not simply reuse your game's standard artwork. Players should immediately recognize that this represents something new and significant.`,
  _ = `The event description should be thoughtfully built to explain the update and why it matters. Use this as your chance to bring players back into your game:`,
  _ = `Highlight the new and exciting content.`,
  _ = `Get creative with images, trailers, or short clips.`,
  _ = `Make the case for why players should care, return, and engage.`,
  _ = `This is your opportunity to sell the update, not just announce it.`,
